using System.ComponentModel.DataAnnotations;
namespace Staybnb.ViewModels;
public class RegisterViewModel { [Required, StringLength(100)] public string FullName{get;set;}=""; [Required,EmailAddress] public string Email{get;set;}=""; [Required,DataType(DataType.Password),MinLength(8)] public string Password{get;set;}=""; [Required,DataType(DataType.Password),Compare(nameof(Password))] public string ConfirmPassword{get;set;}=""; }
public class LoginViewModel { [Required,EmailAddress] public string Email{get;set;}=""; [Required,DataType(DataType.Password)] public string Password{get;set;}=""; public bool RememberMe{get;set;} }
public class PropertyApplicationViewModel { [Required, StringLength(120)] public string Title{get;set;}=""; [Required, StringLength(3000)] public string Description{get;set;}=""; [Range(1,10000000)] public decimal PricePerNight{get;set;} [Range(0,1000000)] public decimal CleaningFee{get;set;} [Range(0,1000000)] public decimal ServiceFee{get;set;} [Range(1,50)] public int Capacity{get;set;}=2; [Required] public string Address{get;set;}=""; [Required] public string City{get;set;}=""; [Required] public string PropertyType{get;set;}="Apartment"; [Required] public List<IFormFile> Images{get;set;}=new(); }
public class BookingViewModel { public int PropertyId{get;set;} [Required,DataType(DataType.Date)] public DateTime CheckInDate{get;set;}=DateTime.Today.AddDays(7); [Required,DataType(DataType.Date)] public DateTime CheckOutDate{get;set;}=DateTime.Today.AddDays(8); [Range(1,50)] public int NumberOfGuests{get;set;}=1; }
public class MessageViewModel { [Required] public string ReceiverId{get;set;}=""; [Required, StringLength(4000)] public string Content{get;set;}=""; }
public class CheckInProcessViewModel { public int PropertyId{get;set;} [Required] public string Title{get;set;}="Guest check-in"; [Required] public string Steps{get;set;}="Review instructions\nUpload required document"; [Required] public string RequiredDocuments{get;set;}="ID or passport"; }
public class HostPropertyEditViewModel { public int Id{get;set;} [Required,StringLength(120)] public string Title{get;set;}=""; [Required,StringLength(3000)] public string Description{get;set;}=""; [Range(1,10000000)] public decimal PricePerNight{get;set;} [Range(0,1000000)] public decimal CleaningFee{get;set;} [Range(0,1000000)] public decimal ServiceFee{get;set;} [Range(1,50)] public int Capacity{get;set;}=2; [Required] public string Address{get;set;}=""; [Required] public string City{get;set;}=""; [Required] public string PropertyType{get;set;}="Apartment"; public List<IFormFile> NewImages{get;set;}=new(); }
